-- STARK R02 synthetic fixture; not a recovered historical dataset.
-- Data only. Apply only to an independently authorized empty fixture database.
BEGIN;
SET LOCAL search_path TO pg_catalog, public;
SET CONSTRAINTS public.employees_manager_fk DEFERRED;
DO $stark_r02$
DECLARE item record; seq text; parts text[];
BEGIN
  FOR item IN SELECT * FROM (VALUES
    ('divisions', 'division_id', 11),
    ('locations', 'location_id', 8),
    ('departments', 'department_id', 38),
    ('positions', 'position_id', 21),
    ('employees', 'employee_id', 501),
    ('employee_compensation', 'compensation_id', 951),
    ('payroll_runs', 'payroll_run_id', 25),
    ('payroll_results', 'payroll_result_id', 9185),
    ('payroll_earnings', 'payroll_earning_id', 18365),
    ('payroll_deductions', 'payroll_deduction_id', 18369),
    ('leave_balances', 'leave_balance_id', 2611),
    ('hr_bp_assignments', 'hr_bp_assignment_id', 7)
  ) AS v(table_name, column_name, next_id) LOOP
    seq := pg_catalog.pg_get_serial_sequence('public.' || item.table_name, item.column_name);
    IF seq IS NULL THEN RAISE EXCEPTION 'Missing fixture identity sequence'; END IF;
    parts := pg_catalog.parse_ident(seq);
    IF array_length(parts, 1) <> 2 OR parts[1] <> 'public' THEN RAISE EXCEPTION 'Unexpected fixture sequence'; END IF;
    EXECUTE pg_catalog.format('ALTER SEQUENCE %I.%I RESTART WITH %s', parts[1], parts[2], item.next_id);
  END LOOP;
END;
$stark_r02$;
SET CONSTRAINTS ALL IMMEDIATE;
COMMIT;
